def choose_move(observation):
    width = observation.get("grid_width", observation.get("width", 0))
    height = observation.get("grid_height", observation.get("height", 0))
    pos = observation.get("self_position", observation.get("position", {"x":0,"y":0}))
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    opp = observation.get("opponent_position", observation.get("opponent", {"x":0,"y":0}))
    ox = opp.get("x", 0)
    oy = opp.get("y", 0)

    dx = 0
    dy = 0

    # basic heuristic: move away from opponent if close
    if abs(x - ox) <= 1 and abs(y - oy) <= 1:
        if x < ox:
            dx = -1
        elif x > ox:
            dx = 1
        if y < oy:
            dy = -1
        elif y > oy:
            dy = 1
        if dx == 0 and dy == 0:
            dx = 1

    # try to move toward a resource if available and not colliding with wall
    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        best = None
        best_d = 1e9
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            d = abs(x - rx) + abs(y - ry)
            if d < best_d:
                best_d = d
                best = (rx, ry)
        if best is not None and best_d > 0:
            rx, ry = best
            if x < rx:
                dx = 1
            elif x > rx:
                dx = -1
            if y < ry:
                dy = 1
            elif y > ry:
                dy = -1

    # stay within bounds
    nx = max(0, min(width - 1, x + dx))
    ny = max(0, min(height - 1, y + dy))

    # ensure movement is valid (non-zero or zero allowed)
    if nx == x and ny == y:
        return [0, 0]
    return [nx - x, ny - y]
